    61|        
    62|        let (data, response) = try await session.data(from: url)
    63|        
    64|        guard let httpResponse = response as? HTTPURLResponse else {
    65|            throw YopmailError.networkError(URLError(.badServerResponse))
    66|        }
    67|        
    68|        if httpResponse.statusCode == 429 {
    69|            throw YopmailError.rateLimited
