    88|    func parseEmails(from html: String) -> [ReceivedEmail] {
    89|        var emails: [ReceivedEmail] = []
    90|        let pattern = #"<div[^>]*class="m"[^>]*>.*?<span[^>]*class="lmf"[^>]*>(.*?)</span>.*?<a[^>]*class="lms"[^>]*>(.*?)</a>.*?<span[^>]*class="lmh"[^>]*>(.*?)</span>.*?<div[^>]*class="lmexcerpt"[^>]*>(.*?)</div>"#
    91|        
    92|        do {
    93|            let regex = try NSRegularExpression(pattern: pattern, options: [.dotMatchesLineSeparators])
    94|            let nsRange = NSRange(html.startIndex..., in: html)
    95|            let matches = regex.matches(in: html, options: [], range: nsRange)
    96|            
    97|            for (index, match) in matches.enumerated() {
    98|                let sender = extractGroup(html, match: match, at: 1)
    99|                let subject = extractGroup(html, match: match, at: 2)
   100|                let timeStr = extractGroup(html, match: match, at: 3)
   101|                let preview = extractGroup(html, match: match, at: 4)
   102|                
   103|                let email = ReceivedEmail(
   104|                    id: "\(sender)_\(index)_\(timeStr)",
   105|                    sender: sender,
   106|                    subject: subject,
   107|                    preview: preview,
   108|                    receivedAt: parseTime(timeStr),
   109|                    isRead: false,
   110|                    bodyHtml: nil
   111|                )
   112|                emails.append(email)
   113|            }
   114|        } catch {
   115|            print("Regex error: \(error)")
   116|        }
   117|        
   118|        return emails
   119|    }
