   121|    private func extractGroup(_ string: String, match: NSTextCheckingResult, at index: Int) -> String {
   122|        guard let range = Range(match.range(at: index), in: string) else { return "" }
   123|        return String(string[range])
   124|            .replacingOccurrences(of: "<[^>]+>", with: "", options: .regularExpression)
   125|            .trimmingCharacters(in: .whitespacesAndNewlines)
   126|    }
