   130|        formatter.dateFormat = "HH:mm"
   131|        if let date = formatter.date(from: timeStr) {
   132|            return date
   133|        }
   134|        formatter.dateFormat = "dd MMM HH:mm"
   135|        return formatter.date(from: timeStr) ?? Date()
   136|    }
