func webView(_ webView: WKWebView, didCommit navigation: WKNavigation!) {
    // Start loading check
    isLoading = true
}

func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction) async -> WKNavigationActionPolicy {
    let url = navigationAction.request.url?.absoluteString ?? ""
    // If navigating to a verification/captcha page, try to intercept and bypass
    if url.contains("verify") || url.contains("captcha") || url.contains("challenge") {
        if let login = url.components(separatedBy: "login=").last?.components(separatedBy: "&").first {
            if let inboxUrl = yopmailService.buildInboxURL(username: login) {
                loadURL(inboxUrl)
                return .cancel
            }
        }
    }
    return .allow
}

